378	/// Forbidden Alchemy reveals top 4, player picks 1 for hand, rest go to graveyard.
379	#[test]
380	fn forbidden_alchemy_draws_and_mills() {
381	    use mtg_engine::actions::ResolvedChoice;
382	
383	    let reg = registry();
384	    let mut state = game_at_step(Step::PrecombatMain, P0);
385	
386	    // Stock library with 5 cards.
387	    let mountain_id = reg.get_id_by_name("Mountain").unwrap();
388	    let mut lib_cards = Vec::new();
389	    for _ in 0..5 {
390	        let obj = state.create_object(mountain_id, P0, Zone::Library, None, None);
391	        state.get_object_mut(obj).unwrap().name = "Mountain".into();
392	        lib_cards.push(obj);
393	    }
394	    state.get_player_mut(P0).library_order = lib_cards.clone();
395	
396	    let hand_before = state.objects_in_zone(Zone::Hand, P0).len();
397	
398	    // Cast Forbidden Alchemy. Cost: {2}{U}.
399	    let fa = castable_spell(&mut state, &reg, "Forbidden Alchemy", P0);
400	
401	    state = cast_and_resolve(&state, &reg, fa, vec![]);
402	
403	    // Should now be awaiting a ChooseFromRevealed choice with 4 revealed cards.
404	    assert!(state.awaiting_action.is_some(), "Should be awaiting a choice");
405	
406	    // Choose the first revealed card (lib_cards[0]) to put into hand.
407	    let keep_card = lib_cards[0];
408	    state = engine::submit_action(
409	        &state,
410	        &Action::ResolveChoice { choice: ResolvedChoice::ChosenCard(keep_card) },
411	        &reg,
412	    );
413	
414	    let hand_after = state.objects_in_zone(Zone::Hand, P0).len();
415	    // Cast from hand (-1), chose 1 to hand (+1) => net 0 from hand_before, but the chosen card is from library.
416	    assert_eq!(hand_after, hand_before + 1,
417	        "Forbidden Alchemy should put 1 card into hand (net +1 after spell leaves hand)");
418	
419	    // 3 cards should have been sent to graveyard (the other revealed cards).
420	    let gy_lib_cards = lib_cards.iter()
421	        .filter(|&&id| state.get_object(id).unwrap().zone == Zone::Graveyard)
422	        .count();
423	    assert_eq!(gy_lib_cards, 3,
