756	/// Check if a permanent can be targeted by a spell from the given caster.
757	/// Returns false if the target has hexproof and the caster is an opponent.
758	fn can_be_targeted(state: &GameState, target_id: ObjectId, caster: PlayerId, registry: &CardRegistry) -> bool {
759	    if state.has_keyword(target_id, Keyword::Hexproof, registry) {
760	        let controller = state.get_object(target_id)
761	            .map(|o| o.controller)
762	            .unwrap_or(PlayerId(255));
763	        if controller != caster {
764	            return false; // hexproof: can't be targeted by opponents
765	        }
766	    }
767	    true
768	}
769	
770	/// Check if a player can be targeted by a given caster.
771	/// Players with hexproof can't be targeted by opponents.
772	fn can_target_player(state: &GameState, target_player: PlayerId, caster: PlayerId, registry: &CardRegistry) -> bool {
773	    if target_player != caster && state.player_has_hexproof(target_player, registry) {
774	        return false;
775	    }
776	    true
777	}
