779	/// Determine which mode of a ModalChoice was selected, based on the chosen targets.
780	/// For each mode, checks if all chosen targets are valid. Returns the first matching
781	/// mode index, defaulting to 0 if ambiguous (e.g. empty targets valid for all modes).
782	fn detect_modal_choice_mode(
783	    state: &GameState,
784	    caster: PlayerId,
785	    spell_id: ObjectId,
786	    targets: &[crate::actions::Target],
787	    modes: &[crate::cards::TargetRequirement],
788	    behavior: &dyn crate::cards::CardBehavior,
789	) -> usize {
790	    let registry = &CardRegistry::with_all_cards();
791	    // For non-empty targets, find the first mode whose valid targets contain all chosen targets.
792	    if !targets.is_empty() {
793	        for (i, mode_req) in modes.iter().enumerate() {
794	            let valid = valid_targets_for_mode(state, caster, spell_id, mode_req, behavior, registry);
795	            if targets.iter().all(|t| valid.contains(t)) {
796	                return i;
797	            }
798	        }
799	    }
800	    // For empty targets (or no mode matched), default to mode 0.
801	    0
802	}
