804	/// Get valid targets for a single mode requirement, unwrapping UpToTargets.
805	fn valid_targets_for_mode(
806	    state: &GameState,
807	    caster: PlayerId,
808	    spell_id: ObjectId,
809	    mode_req: &crate::cards::TargetRequirement,
810	    behavior: &dyn crate::cards::CardBehavior,
811	    registry: &CardRegistry,
812	) -> Vec<crate::actions::Target> {
813	    use crate::cards::TargetRequirement;
814	    match mode_req {
815	        TargetRequirement::UpToTargets(_, inner) => valid_targets_for_req(state, caster, spell_id, inner, behavior, registry),
816	        other => valid_targets_for_req(state, caster, spell_id, other, behavior, registry),
817	    }
818	}
